SELECT ps.project_stack_id AS projectStackId, ps.project_id AS projectId, ps.stack_id AS stackId, s.stack_name AS stackName, s.category AS category, ps.stack_level AS stackLevel, ps.stack_year AS stackYear FROM project_stacks ps JOIN stacks s ON s.stack_id = ps.stack_id WHERE ps.project_id IN
#{id}
ORDER BY ps.project_id, s.category, s.stack_name
